1233	async function loadCompanyInviteRecords(
1234	  db: Db,
1235	  companyId: string,
1236	  options: {
1237	    state?: "active" | "accepted" | "expired" | "revoked";
1238	    limit: number;
1239	    offset: number;
1240	  },
1241	) {
1242	  const whereClause = inviteStateWhereClause(options.state);
1243	  const rows = await db
1244	    .select()
1245	    .from(invites)
1246	    .where(whereClause ? and(eq(invites.companyId, companyId), whereClause) : eq(invites.companyId, companyId))
1247	    .orderBy(desc(invites.createdAt))
1248	    .limit(options.limit + 1)
1249	    .offset(options.offset);
1250	  const hasMore = rows.length > options.limit;
1251	  const visibleRows = hasMore ? rows.slice(0, options.limit) : rows;
1252	  const userIds = [
1253	    ...new Set(
1254	      visibleRows
1255	        .map((invite) => invite.invitedByUserId)
1256	        .filter((value): value is string => Boolean(value)),
1257	    ),
1258	  ];
1259	  const [userMap, joinRows, companyName] = await Promise.all([
1260	    loadUsersById(db, userIds),
1261	    visibleRows.length
1262	      ? db
1263	          .select({ id: joinRequests.id, inviteId: joinRequests.inviteId })
1264	          .from(joinRequests)
1265	          .where(
1266	            and(
1267	              eq(joinRequests.companyId, companyId),
1268	              inArray(
1269	                joinRequests.inviteId,
1270	                visibleRows.map((invite) => invite.id),
1271	              ),
1272	            ),
1273	          )
1274	      : Promise.resolve([]),
1275	    db
1276	      .select({ name: companies.name })
1277	      .from(companies)
1278	      .where(eq(companies.id, companyId))
1279	      .then((companyRows) => companyRows[0]?.name ?? null),
1280	  ]);
1281	  const joinRequestIdByInviteId = new Map(
1282	    joinRows.map((row: { inviteId: string; id: string }) => [row.inviteId, row.id]),
1283	  );
1284	
1285	  return {
1286	    invites: visibleRows.map((invite) => ({
1287	      ...invite,
1288	      companyName,
1289	      humanRole: extractInviteHumanRole(invite),
1290	      inviteMessage: extractInviteMessage(invite),
1291	      state: inviteState(invite),
1292	      invitedByUser: invite.invitedByUserId
1293	        ? userMap.get(invite.invitedByUserId) ?? null
1294	        : null,
1295	      relatedJoinRequestId: joinRequestIdByInviteId.get(invite.id) ?? null,
1296	    })),
1297	    nextOffset: hasMore ? options.offset + options.limit : null,
1298	  };
1299	}
